            gu: 'ઊંચું T4 સ્તર અતિસક્રિય થાઇરોઇડ દર્શાવે છે, જેનાથી ચયાપચય વધે છે અને પરસેવો કે અસ્વસ્થતા જેવા લક્ષણો થાય છે.',
