            gu: 'વિટામિન ડીની ઉણપ સામાન્ય છે, જે હાડકાંને નબળા પાડે છે અને સ્नाયુઓમાં દુખાવો લાવે છે. સપ્લિમેન્ટ્સ લેવાની સલાહ અપાય છે.',
