            ta: 'Mean Corpuscular Hemoglobin (MCH) அளவு குறைவாக உள்ளது, இது ஏற்றத்தாழ்வைக் குறிக்கலாம். உங்கள் மருத்துவரிடம் ஆலோசனை பெறவும்.',
